  return new Promise((r) => setTimeout(r, ms * Math.random()));
}

async function retry(fn, maxRetries) {
  for (let i = 0; i <= maxRetries; i += 1) {
    try { return await fn(); } catch (_err) {}
  }
  throw new Error('failed');
}

async function retry(fn, maxRetries, baseMs, maxMs, sleep) {
  for (let i = 0; i <= maxRetries; i += 1) {
    try { return await fn(); } catch (e) {
      if (i === maxRetries) throw e;
      await sleep(Math.random() * Math.min(maxMs, baseMs * (2 ** i)));
    }
  }
  return undefined;
}

async function runPool(items, fn) {
  return Promise.all(items.map((item) => fn(item)));
}

async function runPool(items, fn, concurrency) {
  const workers = Array.from({ length: Math.max(0, concurrency) }, () => Promise.resolve());
  if (concurrency <= 0) throw new Error('Invalid concurrency');
  await Promise.all(workers);
  return items.map(fn);
}

async function runPool(items, fn, concurrency) {
  const results = [];
  for (let i = 0; i < concurrency; i += 1) {
    void fn(items[i]).then((v) => results.push(v));
  }
  return results;
}

function onResult(state, ok, threshold) {
  if (ok) state.mode = 'CLOSED';
  else {
    state.failures += 1;
    if (state.failures >= threshold) state.mode = 'OPEN';
  }
}

function isCooldownElapsed(openedAt, resetMs) {
